import Foundation

struct AttributeCenter {
    let chart: String
    let value: Double
    let fraction: Double
}
struct LotPoint {
    let lot: Lot
    let value: Double
    let lcl: Double
    let ucl: Double
    let z: Double
    let status: String
}
func attributeCenter(_ chart: String, _ lots: [Lot]) -> AttributeCenter {
    let defectives = lots.reduce(0) { $0 + $1.defectives }
    let defects = lots.reduce(0) { $0 + $1.defects }
    let inspected = lots.reduce(0) { $0 + $1.inspected }
    let fraction = Double(defectives) / Double(inspected)
    let center: Double
    switch chart {
    case "p": center = fraction
    case "np": center = Double(defectives) / Double(lots.count)
    case "c": center = Double(defects) / Double(lots.count)
    default: center = Double(defects) / Double(inspected)
    }
    return AttributeCenter(chart: chart, value: center, fraction: fraction)
}
func attributePoint(_ lot: Lot, _ center: AttributeCenter) -> LotPoint {
    let cl = center.value
    let value: Double
    let sigma: Double
    switch center.chart {
    case "p": value = Double(lot.defectives) / Double(lot.inspected); sigma = sqrt(cl * (1 - cl) / Double(lot.inspected))
    case "np": value = Double(lot.defectives); sigma = sqrt(cl * (1 - center.fraction))
    case "c": value = Double(lot.defects); sigma = sqrt(cl)
    default: value = Double(lot.defects) / Double(lot.inspected); sigma = sqrt(cl / Double(lot.inspected))
    }
    let lcl = max(0, cl - 3 * sigma)
    let ucl = cl + 3 * sigma
    let status = value > ucl ? "high" : value < lcl ? "low" : "ok"
    return LotPoint(lot: lot, value: value, lcl: lcl, ucl: ucl, z: (value - cl) / sigma, status: status)
}

import Foundation

struct TargetSample {
    let number: Int
    let subgroup: Int
    let value: Int
}
struct Capability {
    let metrics: [(String, Double)]
    let samples: [TargetSample]
    let below: Int
    let above: Int
    func value(_ name: String) -> Double { metrics.first { $0.0 == name }!.1 }
    var verdict: String { value("cpk") >= 1.33 ? "capable" : value("cpk") >= 1 ? "marginal" : "incapable" }
}
func capability(_ ids: [Int], _ groups: [Subgroup], _ settings: Settings, _ constants: ControlConstants) -> Capability {
    let selected = ids.map { groups[$0 - 1] }
    let samples = selected.flatMap { group in group.values.enumerated().map { TargetSample(number: (group.number - 1) * settings.size + $0.offset + 1, subgroup: group.number, value: $0.element) } }
    let count = samples.count
    let mean = Double(samples.reduce(0) { $0 + $1.value }) / Double(count)
    let within = Double(selected.reduce(0) { $0 + $1.range }) / Double(selected.count) / constants.d2
    let sbar = realSum(selected.map(\.sd)) / Double(selected.count) / constants.c4
    var squared = 0.0
    for sample in samples { let difference = Double(sample.value) - mean; squared += difference * difference }
    let overall = sqrt(squared / Double(count - 1))
    let cp = Double(settings.usl - settings.lsl) / (6 * within)
    let cpu = (Double(settings.usl) - mean) / (3 * within)
    let cpl = (mean - Double(settings.lsl)) / (3 * within)
    let cpk = min(cpu, cpl)
    let pp = Double(settings.usl - settings.lsl) / (6 * overall)
    let ppu = (Double(settings.usl) - mean) / (3 * overall)
    let ppl = (mean - Double(settings.lsl)) / (3 * overall)
    let ppk = min(ppu, ppl)
    let offset = mean - Double(settings.target)
    let cpm = Double(settings.usl - settings.lsl) / (6 * sqrt(overall * overall + offset * offset))
    let below = samples.filter { $0.value < settings.lsl }.count
    let above = samples.filter { $0.value > settings.usl }.count
    let ppm = Double(1_000_000 * (below + above)) / Double(count)
    return Capability(metrics: [("mean", mean), ("sigma_within", within), ("sigma_sbar", sbar), ("sigma_overall", overall), ("cp", cp), ("cpu", cpu), ("cpl", cpl), ("cpk", cpk), ("pp", pp), ("ppu", ppu), ("ppl", ppl), ("ppk", ppk), ("cpm", cpm), ("ppm", ppm)], samples: samples, below: below, above: above)
}
func confidence(_ index: Double, _ count: Int, _ z: Double) -> (Double, Double) {
    let delta = z * sqrt(1 / Double(9 * count) + index * index / Double(2 * (count - 1)))
    return (index - delta, index + delta)
}
func histogram(_ capability: Capability, _ settings: Settings) -> [String] {
    let values = capability.samples.map(\.value)
    let low = settings.bin * (min(values.min()!, settings.lsl) / settings.bin)
    let high = settings.bin * (max(values.max()!, settings.usl) / settings.bin) + settings.bin
    var counts: [Int: Int] = [:]
    for value in values { counts[settings.bin * (value / settings.bin), default: 0] += 1 }
    let top = counts.values.max()!
    var lines: [String] = []
    for start in stride(from: low, to: high, by: settings.bin) {
        let end = start + settings.bin - 1
        let frequency = counts[start, default: 0]
        let length = (50 * frequency + top - 1) / top
        var parts = ["bin", String(start), String(end), String(frequency)]
        if length > 0 { parts.append(String(repeating: "#", count: length)) }
        if (start...end).contains(settings.lsl) { parts.append("lsl") }
        if (start...end).contains(settings.target) { parts.append("target") }
        if (start...end).contains(settings.usl) { parts.append("usl") }
        lines.append(parts.joined(separator: " "))
    }
    return lines
}

import Foundation

struct Settings {
    let characteristic: String
    let lsl: Int
    let usl: Int
    let target: Int
    let size: Int
    let phase1: Int
    let passes: Int
    let rules: [String: [Int]]
    let cusumK: Double
    let cusumH: Double
    let lambda: Double
    let ewmaL: Double
    let maSpan: Int
    let eventGap: Int
    let ciZ: Double
    let bin: Int
    let rollingWindow: Int
    let rollingStep: Int

    init(_ lines: [String]) {
        var fields: [String: String] = [:]
        var rules: [String: [Int]] = [:]
        for line in lines {
            let words = line.split(separator: " ").map(String.init)
            if words[0] == "rules" { rules[words[1]] = words.dropFirst(2).map { Int($0)! } }
            else { fields[words[0]] = words[1] }
        }
        characteristic = fields["characteristic"]!
        lsl = Int(fields["lsl"]!)!
        usl = Int(fields["usl"]!)!
        target = Int(fields["target"]!)!
        size = Int(fields["subgroup_size"]!)!
        phase1 = Int(fields["phase1_subgroups"]!)!
        passes = Int(fields["max_passes"]!)!
        self.rules = rules
        cusumK = Double(fields["cusum_k"]!)!
        cusumH = Double(fields["cusum_h"]!)!
        lambda = Double(fields["ewma_lambda"]!)!
        ewmaL = Double(fields["ewma_l"]!)!
        maSpan = Int(fields["ma_span"]!)!
        eventGap = Int(fields["event_gap"]!)!
        ciZ = Double(fields["ci_z"]!)!
        bin = Int(fields["histogram_bin"]!)!
        rollingWindow = Int(fields["rolling_window"]!)!
        rollingStep = Int(fields["rolling_step"]!)!
    }
}
struct Lot {
    let number: Int
    let inspected: Int
    let defectives: Int
    let defects: Int
}
