import Foundation

func put(_ band: inout [Character], _ position: Double, _ symbol: Character) { band[Int(min(60, max(0, position)))] = symbol }
func variableBand(_ limits: Limits, _ value: Double, _ signalled: Bool) -> String {
    var band = Array(repeating: Character("."), count: 61)
    func position(_ value: Double) -> Double { floor(60 * ((value - limits.lcl) / (limits.ucl - limits.lcl)) + 0.5) }
    put(&band, 0, ":"); put(&band, 60, ":"); put(&band, position(limits.cl), "|"); put(&band, position(value), signalled ? "*" : "o")
    return String(band)
}
func cusumBand(_ upper: Double, _ lower: Double, _ threshold: Double, _ highSignal: Bool, _ lowSignal: Bool) -> String {
    var band = Array(repeating: Character("."), count: 61)
    put(&band, 0, ":"); put(&band, 60, ":"); put(&band, 30, "|")
    if lower > 0 { put(&band, 30 - min(30, floor(30 * (lower / threshold) + 0.5)), lowSignal ? "*" : "-") }
    if upper > 0 { put(&band, 30 + min(30, floor(30 * (upper / threshold) + 0.5)), highSignal ? "*" : "+") }
    return String(band)
}
func smoothBand(_ width: Double, _ rowWidth: Double, _ value: Double, _ center: Double, _ signalled: Bool) -> String {
    var band = Array(repeating: Character("."), count: 61)
    let edge = min(30, floor(30 * (rowWidth / width) + 0.5))
    put(&band, 30, "|"); put(&band, 30 - edge, ":"); put(&band, 30 + edge, ":")
    put(&band, 30 + floor(30 * ((value - center) / width) + 0.5), signalled ? "*" : "o")
    return String(band)
}
func standardBand(_ z: Double, _ okay: Bool) -> String {
    var band = Array(repeating: Character("."), count: 61)
    put(&band, 0, ":"); put(&band, 60, ":"); put(&band, 30, "|"); put(&band, 30 + floor(10 * z + 0.5), okay ? "o" : "*")
    return String(band)
}

struct Point {
    let number: Int
    let value: Double
}
struct Signal {
    let chart: String
    let rule: String
    let start: Int
    let end: Int
    let value: Double
    let direction: String
    func subgroup(_ size: Int) -> Int { chart == "I" || chart == "MR" ? (end - 1) / size + 1 : end }
}
struct Zones {
    let upper1: Double
    let upper2: Double
    let lower1: Double
    let lower2: Double
    init(_ limits: Limits) {
        let above = (limits.ucl - limits.cl) / 3
        let below = (limits.cl - limits.lcl) / 3
        upper1 = limits.cl + above
        upper2 = limits.cl + 2 * above
        lower1 = limits.cl - below
        lower2 = limits.cl - 2 * below
    }
}
func zoneName(_ value: Double, _ limits: Limits) -> String {
    let zone = Zones(limits)
    if value > limits.ucl { return "OUT+" }
    if value < limits.lcl { return "OUT-" }
    if value > zone.upper2 { return "A+" }
    if value > zone.upper1 { return "B+" }
    if value > limits.cl { return "C+" }
    if value < zone.lower2 { return "A-" }
    if value < zone.lower1 { return "B-" }
    return value < limits.cl ? "C-" : "C0"
}
func runRules(_ chart: String, _ points: [Point], _ limits: Limits, _ rules: [Int]) -> [Signal] {
    let lengths = [0, 1, 3, 5, 8, 6, 14, 15, 8]
    let zone = Zones(limits)
    var signals: [Signal] = []
    for index in points.indices {
        for rule in rules {
            let length = lengths[rule]
            if index + 1 < length { continue }
            let window = points[(index + 1 - length)...index].map(\.value)
            let value = window.last!
            var direction: String?
            switch rule {
            case 1: if limits.outside(value) { direction = value > limits.cl ? "UP" : "DOWN" }
            case 2:
                if value > zone.upper2 && window.filter({ $0 > zone.upper2 }).count >= 2 { direction = "UP" }
                else if value < zone.lower2 && window.filter({ $0 < zone.lower2 }).count >= 2 { direction = "DOWN" }
            case 3:
                if value > zone.upper1 && window.filter({ $0 > zone.upper1 }).count >= 4 { direction = "UP" }
                else if value < zone.lower1 && window.filter({ $0 < zone.lower1 }).count >= 4 { direction = "DOWN" }
            case 4:
                if window.allSatisfy({ $0 > limits.cl }) { direction = "UP" }
                else if window.allSatisfy({ $0 < limits.cl }) { direction = "DOWN" }
            case 5:
                if zip(window, window.dropFirst()).allSatisfy({ pair in pair.1 > pair.0 }) { direction = "UP" }
                else if zip(window, window.dropFirst()).allSatisfy({ pair in pair.1 < pair.0 }) { direction = "DOWN" }
            case 6:
                let differences = zip(window, window.dropFirst()).map { pair in pair.1 - pair.0 }
                if differences.allSatisfy({ $0 != 0 }) && zip(differences, differences.dropFirst()).allSatisfy({ pair in (pair.0 > 0) != (pair.1 > 0) }) { direction = "NONE" }
            case 7: if window.allSatisfy({ $0 > zone.lower1 && $0 < zone.upper1 }) { direction = "NONE" }
            default:
                if window.allSatisfy({ $0 > zone.upper1 || $0 < zone.lower1 }) && window.contains(where: { $0 > zone.upper1 }) && window.contains(where: { $0 < zone.lower1 }) { direction = "NONE" }
            }
            if let direction { signals.append(Signal(chart: chart, rule: String(rule), start: points[index + 1 - length].number, end: points[index].number, value: value, direction: direction)) }
        }
    }
    return signals
}

import Foundation

struct Subgroup {
    let number: Int
    let values: [Int]
    let total: Int
    let squares: Int
    let mean: Double
    let range: Int
    let sd: Double
    init(number: Int, values: [Int]) {
        self.number = number
        self.values = values
        total = values.reduce(0, +)
        squares = values.reduce(0) { $0 + $1 * $1 }
        mean = Double(total) / Double(values.count)
        range = values.max()! - values.min()!
        sd = sqrt(Double(values.count * squares - total * total) / Double(values.count * (values.count - 1)))
    }
}
struct Limits {
    let lcl: Double
    let cl: Double
    let ucl: Double
    func outside(_ value: Double) -> Bool { value < lcl || value > ucl }
}
struct FamilyLimits {
    let first: Limits
    let second: Limits
}
func realSum(_ values: [Double]) -> Double {
    var result = 0.0
    for value in values { result += value }
    return result
}
func familyLimits(_ family: String, _ ids: [Int], _ groups: [Subgroup], _ samples: [Int], _ size: Int, _ constants: ControlConstants) -> FamilyLimits {
    if family == "I_MR" {
        let values = ids.map { samples[$0 - 1] }
        let mean = Double(values.reduce(0, +)) / Double(values.count)
        let ranges = zip(values, values.dropFirst()).map { pair in abs(pair.1 - pair.0) }
        let moving = Double(ranges.reduce(0, +)) / Double(ranges.count)
        let pair = controlConstants(2)
        return FamilyLimits(first: Limits(lcl: mean - 3 * moving / pair.d2, cl: mean, ucl: mean + 3 * moving / pair.d2), second: Limits(lcl: pair.d3 * moving, cl: moving, ucl: pair.d4 * moving))
    }
    let selected = ids.map { groups[$0 - 1] }
    let mean = Double(selected.reduce(0) { $0 + $1.total }) / Double(ids.count * size)
    if family == "XBAR_R" {
        let range = Double(selected.reduce(0) { $0 + $1.range }) / Double(selected.count)
        return FamilyLimits(first: Limits(lcl: mean - constants.a2 * range, cl: mean, ucl: mean + constants.a2 * range), second: Limits(lcl: constants.d3 * range, cl: range, ucl: constants.d4 * range))
    }
    let sd = realSum(selected.map(\.sd)) / Double(selected.count)
    return FamilyLimits(first: Limits(lcl: mean - constants.a3 * sd, cl: mean, ucl: mean + constants.a3 * sd), second: Limits(lcl: constants.b3 * sd, cl: sd, ucl: constants.b4 * sd))
}
